// All the code below is javascript that's compiled into a shader
// Find more info at www.shaderpark.com

const shaderParkCode =  `
	let currTime = time*.4;
  let click = input();
	let buttonHover = input();
	rotateX(mouse.y)
	rotateY(mouse.x)
	let s = getSpace();
	let nscale = .2//.20 * (click) +.1;
	let rings = 10 + click*40

	let samplePos = s * nscale + vec3(0, 0, -1 * currTime) * .2
	let n1 = nsin((noise(samplePos)) * rings);
	color(pow(vec3(n1 * 1.5), vec3(6)))


	let background = shape(() => {
		occlusion(.9)
		sphere(2.3);
		shell(.005);
	});

	let spheres = shape(() => {
		background()
		occlusion(.9)
		metal(0)
		shine(0)
		rotateX(getRayDirection().x*10*click)
		rotateZ(currTime);
		rotateY(currTime);
		mirrorN(2,  .18  );
		sphere(.1);
		reset();
		difference();
		sphere(.65);
	})

	// background();
	spheres();
	mixGeo(click);
	mirrorXYZ();
	spheres();


`;


